sources.app.tsx:
// A web browser on the frame's screen. Type an address (or words to search
// for), and the page is downloaded, cleaned and drawn as JSX: html.ts reads
// the HTML in one pass and keeps the text, links, pictures, tables, lists and
// GET forms, with the colors and sizes its style sheets give them (css.ts);
// scripts, styles, frames, video and hidden parts are dropped. view.tsx draws
// what is left, and a tap on a link opens it here. Hold a link for its menu:
// open it, or show its QR code to open it on a phone.
//
// The page downloads with frameos.useFetch: off the render where the frame
// pumps promises (a tap answers at once and the page follows), in the render
// where it does not (e-paper: one refresh with the page). Back and forward are
// the toolbar's arrows and the frame's own back / forward (a HyperPixel's edge
// swipes, a reTerminal's keys). Where you have been is kept with
// frameos.remember, so a frame that let the interpreter go opens on the same
// page, scrolled where it was. Built and tested against Hacker News.

import { convert, scanHead, type Page } from './html'
import { jsxSource, renderPage, type Act } from './view'

const HOME = 'https://news.ycombinator.com/'
const SEARCH = 'https://lite.duckduckgo.com/lite/?q='
const MAX_HISTORY = 40
const MAX_HTML = 1536 * 1024
const MAX_CSS = 256 * 1024
const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (compatible; FrameOS browser)',
  Accept: 'text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5',
}
const ZOOMS = [0.6, 0.7, 0.8, 0.9, 1, 1.15, 1.3, 1.5, 1.75, 2]

// frameos.useFetch is experimental (docs/async-js.md): the editor's
// declarations do not have it yet.
const useFetch = (url: string, init: Record<string, any>) => (frameos as any).useFetch(url, init)

type Entry = { u: string; y: number }
type Nav = { list: Entry[]; at: number }
type Load = { url: string; n: number; html?: string; status?: number; sheets?: string[] }

let page: Page | null = null // the page showing
let loading: Load | null = null
let loadSeq = 0
let failure: { url: string; why: string } | null = null
let typed: string | null = null // the address while it is being typed
let held = '' // the link whose menu is open
let source = false // the page as JSX
let scrollY = 0 // where the page is scrolled to (UI pixels)
let scrollAttr = 0 // what the page box is told: changed only to move it
let rev = 0 // the fields' values changed
const pages = new Map<string, Page>() // pages seen, newest last
const sheets = new Map<string, string>() // style sheets by URL
const values = new Map<string, string>() // what was typed into a page's fields

const kept = (key: string, empty: any) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

function readNav(app: any): Nav {
  const nav = kept('nav', null)
  if (nav && Array.isArray(nav.list) && nav.list.length) return nav
  return { list: [{ u: homeOf(app), y: 0 }], at: 0 }
}
const saveNav = (nav: Nav) => frameos.remember('nav', nav)
const homeOf = (app: any) => normalize(String(app.state.homepage || app.config.homepage || HOME)) || HOME

// What was typed as a URL: an address, or words to search for.
export function normalize(text: string): string {
  const t = text.trim()
  if (!t) return ''
  if (/^https?:\/\//i.test(t)) return t
  if (/^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(t) || /^localhost(:\d+)?(\/|$)/.test(t)) return 'http' + (/^(localhost|\d+\.\d+\.\d+\.\d+)/.test(t) ? '' : 's') + '://' + t
  return SEARCH + encodeURIComponent(t)
}

// A search result's link is DuckDuckGo's redirect: the page it names instead.
function unwrap(url: string): string {
  const m = /^https?:\/\/(?:html\.|lite\.)?duckduckgo\.com\/l\/\?(?:.*&)?uddg=([^&]+)/.exec(url)
  if (m) {
    try {
      return decodeURIComponent(m[1])
    } catch (e) {
      return url
    }
  }
  return url
}

const appRef: { app: any } = { app: null }

// One app object is one browser: the interpreter's. A new one (a test's
// makeApp) starts with nothing open.
function bind(app: any) {
  if (appRef.app === app) return
  appRef.app = app
  page = null
  loading = null
  failure = null
  typed = null
  held = ''
  source = false
  scrollY = 0
  pages.clear()
  values.clear()
}

function jumpTo(y: number) {
  // scrollTop moves the box only when it changes (docs/jsx-ui.md): the same
  // place again is told a hair apart.
  scrollAttr = scrollAttr === y ? y + 0.01 : y
  scrollY = y
}

function open(url: string) {
  const app = appRef.app
  const nav = readNav(app)
  nav.list[nav.at].y = scrollY
  nav.list = nav.list.slice(0, nav.at + 1)
  nav.list.push({ u: unwrap(url), y: 0 })
  if (nav.list.length > MAX_HISTORY) nav.list = nav.list.slice(-MAX_HISTORY)
  nav.at = nav.list.length - 1
  saveNav(nav)
  typed = null
  held = ''
  source = false
  failure = null
}

function step(by: number): boolean {
  const nav = readNav(appRef.app)
  const at = nav.at + by
  if (at < 0 || at >= nav.list.length) return false
  nav.list[nav.at].y = scrollY
  nav.at = at
  saveNav(nav)
  typed = null
  held = ''
  failure = null
  return true
}

function reload() {
  const nav = readNav(appRef.app)
  pages.delete(nav.list[nav.at].u)
  nav.list[nav.at].y = scrollY
  saveNav(nav)
  page = null
  loading = null
  failure = null
}

function submit(form: number) {
  if (!page || !page.forms[form]) return
  const f = page.forms[form]
  const parts: string[] = []
  f.fields.forEach((field, i) => {
    if (field.type === 'submit') return
    const value = values.get(`${page!.url}|${form}|${i}`) ?? field.value
    parts.push(encodeURIComponent(field.name) + '=' + encodeURIComponent(value).replace(/%20/g, '+'))
  })
  open(f.action + (parts.length ? '?' + parts.join('&') : ''))
}

const act: Act = {
  go: (url) => open(url),
  hold: (url) => {
    held = url
  },
  value: (form, field) => {
    const key = `${page ? page.url : ''}|${form}|${field}`
    return values.get(key) ?? (page && page.forms[form] ? page.forms[form].fields[field].value : '')
  },
  type: (form, field, value) => {
    const at = value.indexOf('\n')
    values.set(`${page ? page.url : ''}|${form}|${field}`, at < 0 ? value : value.slice(0, at))
    rev++
    if (at >= 0) submit(form)
  },
  submit,
}

// A page from what was downloaded: HTML, plain text, or a picture.
function pageFrom(load: Load, embedded: boolean): Page {
  const html = load.html || ''
  const head = html.slice(0, 2048).trimStart().toLowerCase()
  const isHtml = head.startsWith('<') || /<(html|body|div|p|table|a|head)[\s>]/.test(head)
  const text = isHtml
    ? html
    : '<pre>' + html.slice(0, 200000).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>'
  const css = (load.sheets || []).map((u) => sheets.get(u) || '')
  return convert(text, load.url, { sheets: css, maxImages: embedded ? 12 : 40, maxRuns: embedded ? 8000 : 30000 })
}

function imagePage(url: string): Page {
  return {
    url,
    title: url.slice(url.lastIndexOf('/') + 1),
    bg: '#202020',
    root: { k: 'b', c: [{ k: 't', align: 'center', pre: false, runs: [{ img: url, w: 0, h: 0, alt: '' }] }] },
    forms: [],
    truncated: false,
    stats: { runs: 1, images: 1, links: 0 },
  }
}

function remember(p: Page, embedded: boolean) {
  pages.delete(p.url)
  pages.set(p.url, p)
  while (pages.size > (embedded ? 1 : 4)) pages.delete(pages.keys().next().value as string)
}

// Moves the download of `url` along: the page, then its style sheets, then the
// page drawn. Returns the page once it is in.
function fetchPage(url: string, embedded: boolean): Page | null {
  if (!loading || loading.url !== url) loading = { url, n: ++loadSeq }
  const load = loading
  if (/\.(png|jpe?g|gif|webp|bmp|svg)(\?[^/]*)?$/i.test(url)) {
    loading = null
    return imagePage(url)
  }
  if (load.html === undefined) {
    const answer = useFetch(url, { as: 'text', headers: HEADERS, timeoutMs: 20000, n: load.n })
    if (answer.loading && answer.data === undefined) return null
    if (answer.error || (answer.data === undefined && !answer.ok)) {
      failure = { url, why: answer.error || `HTTP ${answer.status}` }
      loading = null
      return null
    }
    load.html = String(answer.data ?? '').slice(0, MAX_HTML)
    load.status = answer.status
    answer.data = '' // the text is drawn from here on: let it go
    load.sheets = scanHead(load.html, url).sheets
  }
  for (const sheet of load.sheets || []) {
    if (sheets.has(sheet)) continue
    const answer = useFetch(sheet, { as: 'text', headers: HEADERS, timeoutMs: 10000 })
    if (answer.loading && answer.data === undefined) return null
    sheets.set(sheet, answer.ok ? String(answer.data ?? '').slice(0, MAX_CSS) : '')
    answer.data = ''
    while (sheets.size > 8) sheets.delete(sheets.keys().next().value as string)
  }
  const p = pageFrom(load, embedded)
  loading = null
  return p
}

const PageView = memo((props: any) =>
  renderPage(props.page, props.width, { k: props.k, minPx: props.minPx, ink: props.ink }, act)
)

const SourceView = memo((props: any) => {
  const lines = jsxSource(props.page, { k: props.k, minPx: props.minPx, ink: props.ink }, 400)
  return (
    <div className={`flex flex-col p-[8px] bg-[#1e1e1e] text-[#d4d4d4] font-mono text-[${props.minPx + 1}px] leading-[${Math.round((props.minPx + 1) * 1.4)}px]`}>
      {lines.map((line: string) => {
        const indent = line.length - line.trimStart().length
        return (
          <div className="whitespace-nowrap truncate">
            {' '.repeat(indent) + line.trimStart()}
          </div>
        )
      })}
    </div>
  )
})

const ICONS = {
  back: 'M20,11V13H8L13.5,18.5L12.08,19.92L4.16,12L12.08,4.08L13.5,5.5L8,11H20Z',
  forward: 'M4,11V13H16L10.5,18.5L11.92,19.92L19.84,12L11.92,4.08L10.5,5.5L16,11H4Z',
  reload:
    'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  stop: 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z',
  home: 'M10,20V14H14V20H19V12H22L12,3L2,12H5V20H10Z',
  code: 'M14.6,16.6L19.2,12L14.6,7.4L16,6L22,12L16,18L14.6,16.6M9.4,16.6L4.8,12L9.4,7.4L8,6L2,12L8,18L9.4,16.6Z',
  minus: 'M19,13H5V11H19V13Z',
  plus: 'M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z',
}

export function onEvent(app: any, context: any) {
  bind(app)
  if (context.event === 'back') return step(-1)
  if (context.event === 'forward') return step(1)
  return false
}

export function get(app: any, context: any) {
  bind(app)
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const embedded = app.frame.embedded === true
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // The chrome's size by the frame, as the Terminal sample's text: twice it on a
  // 4K screen or large e-paper, smaller under 480.
  const shortSide = Math.min(app.frame.width, app.frame.height)
  const z = shortSide >= (paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : Math.max(0.75, shortSide / 480)
  const zoomAt = Math.max(0, Math.min(ZOOMS.length - 1, Number(kept('zoom', 4))))
  const k = Math.round(z * 1.2 * ZOOMS[zoomAt] * 100) / 100
  const minPx = Math.round(10 * z * Math.min(1, ZOOMS[zoomAt] + 0.1))

  // A new home page in the scene's settings is opened.
  const home = homeOf(app)
  if (kept('home', '') !== home) {
    frameos.remember('home', home)
    if (kept('nav', null)) open(home)
  }

  const nav = readNav(app)
  const entry = nav.list[nav.at]
  if (!page || page.url !== entry.u) {
    const seen = pages.get(entry.u)
    if (seen) {
      page = seen
      jumpTo(entry.y)
    } else if (!failure || failure.url !== entry.u) {
      const p = fetchPage(entry.u, embedded)
      if (p) {
        page = p
        remember(p, embedded)
        jumpTo(entry.y)
      }
    }
  }
  const showing = page && page.url === entry.u ? page : null
  const busy = !showing && !!loading
  const failed = !showing && failure && failure.url === entry.u ? failure.why : ''

  const bar = Math.round(38 * z)
  const icon = Math.round(20 * z)
  const text = Math.round(15 * z)
  const fg = ink ? 'text-[#000000]' : 'text-[#e8e8e8]'
  const button = (path: string, onClick: () => void, enabled = true) => (
    <div
      className={`flex items-center justify-center w-[${bar}px] h-[${bar}px] shrink-0 ${
        enabled ? (ink ? '' : 'active:bg-[#4a4a4a] hover:bg-[#3a3a3a]') : 'opacity-40'
      } cursor-pointer`}
      onClick={enabled ? onClick : () => {}}
    >
      <svg viewBox="0 0 24 24" className={`w-[${icon}px] h-[${icon}px]`}>
        <path d={path} fill="currentColor" />
      </svg>
    </div>
  )
  const address = typed ?? entry.u
  const contentW = width - Math.round(4 * z)

  return (
    <div className={`flex flex-col w-full h-full ${ink ? 'bg-[#ffffff]' : 'bg-[#ffffff]'}`}>
      <div
        className={`flex items-center h-[${bar}px] shrink-0 gap-[${Math.round(2 * z)}px] px-[${Math.round(2 * z)}px] ${
          ink ? 'bg-[#ffffff] border-b border-[#000000]' : 'bg-[#2b2b2b]'
        } ${fg}`}
      >
        {button(ICONS.back, () => step(-1), nav.at > 0)}
        {button(ICONS.forward, () => step(1), nav.at < nav.list.length - 1)}
        {button(busy ? ICONS.stop : ICONS.reload, () => {
          if (busy) {
            loading = null
            failure = { url: entry.u, why: 'Stopped' }
          } else reload()
        })}
        {button(ICONS.home, () => open(homeOf(app)))}
        <input
          className={`flex-1 min-w-0 h-[${bar - Math.round(10 * z)}px] px-[${Math.round(8 * z)}px] rounded-[${Math.round(4 * z)}px] text-[${text}px] ${
            ink ? 'border border-[#000000] text-[#000000] bg-[#ffffff]' : 'bg-[#1a1a1a] text-[#f0f0f0] focus:bg-[#000000]'
          }`}
          value={address}
          placeholder="Search or type an address"
          onChange={(e: any) => {
            typed = String(e.target.value)
          }}
          onKeyDown={(e: any) => {
            if (e.key === 'Enter') {
              const url = normalize(typed ?? address)
              if (url) open(url)
            } else if (e.key === 'Escape') typed = null
          }}
        />
        {button(ICONS.minus, () => frameos.remember('zoom', Math.max(0, zoomAt - 1)), zoomAt > 0)}
        {button(ICONS.plus, () => frameos.remember('zoom', Math.min(ZOOMS.length - 1, zoomAt + 1)), zoomAt < ZOOMS.length - 1)}
        {button(ICONS.code, () => {
          source = !source
          jumpTo(0)
        }, !!showing)}
      </div>
      <div
        className="flex flex-col flex-1 min-h-0 overflow-y-auto"
        scrollTop={scrollAttr}
        onScroll={(e: any) => {
          scrollY = e.scrollTop
        }}
      >
        {showing ? (
          source ? (
            <SourceView page={showing} k={k} minPx={minPx} ink={ink} />
          ) : (
            <PageView page={showing} width={contentW} k={k} minPx={minPx} ink={ink} rev={rev} />
          )
        ) : (
          <div className={`flex flex-col items-center justify-center flex-1 gap-[${Math.round(10 * z)}px] p-[${Math.round(16 * z)}px] text-[#555555] text-[${text}px]`}>
            {failed ? (
              <>
                <span className={`text-[${Math.round(text * 1.3)}px] text-[#222222] font-bold`}>This page did not load</span>
                <span className="text-center">{failed}</span>
                <span className="text-center text-[#888888]">{entry.u}</span>
                <div
                  className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded border border-[#888888] text-[#222222] cursor-pointer`}
                  onClick={() => reload()}
                >
                  Try again
                </div>
              </>
            ) : (
              <>
                <span>{'Loading ' + (entry.u.replace(/^https?:\/\//, '').split('/')[0] || '') + '…'}</span>
              </>
            )}
          </div>
        )}
      </div>
      {held ? (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50" onClick={() => (held = '')}>
          <div
            className={`flex flex-col gap-[${Math.round(8 * z)}px] w-[${Math.min(width - 32, Math.round(440 * z))}px] p-[${Math.round(14 * z)}px] rounded-[${Math.round(8 * z)}px] bg-[#ffffff] text-[#111111] text-[${text}px] ${ink ? 'border-2 border-[#000000]' : ''}`}
            onClick={() => {}}
          >
            <span className={`text-[${Math.round(text * 0.85)}px] text-[#555555] line-clamp-3`}>{held}</span>
            <div className="flex gap-[8px]">
              <div
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded bg-[#ff6600] text-[#ffffff] font-bold cursor-pointer`}
                onClick={() => open(held)}
              >
                Open
              </div>
              <a
                href={held}
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded border border-[#888888] cursor-pointer`}
              >
                QR code
              </a>
              <div
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded border border-[#888888] cursor-pointer`}
                onClick={() => (held = '')}
              >
                Cancel
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  )
}

sources.html.ts:
// HTML to a page this browser can draw, in one pass over the text: a forgiving
// tokenizer feeds a tree builder that keeps only what reads (text, links,
// pictures, tables, lists, headings, GET forms) and drops the rest (scripts,
// styles, frames, video, inline SVG, hidden parts, POST forms). The builder
// never holds the document as a DOM: it keeps a stack of the open elements,
// for the cascade (css.ts) and for the HTML rules that close elements a page
// left open (a <p> before a <div>, a <td> before the next one), and writes
// the page straight into a small tree of boxes, text flows and tables that
// view.tsx turns into JSX.

import { addCss, backgroundOf, colorOf, lengthOf, matching, newSheet, parseDecls, type El, type Sheet } from './css'

// A text style, interned: equal styles are one object (view.tsx keys on it).
export type St = {
  size: number // CSS px
  color: string
  bold: boolean
  italic: boolean
  under: boolean
  strike: boolean
  mono: boolean
  pre: boolean
  align: string // '', 'center', 'right'
  hidden: boolean // visibility: hidden
  key: string
}
// A run of a text flow: text (with its link `a`), a line break, a picture, a
// spacer (an empty picture: Hacker News indents its comments with one), a
// field or a form's button.
export type Run =
  | { x: string; s: St; a?: string }
  | { br: true }
  | { img: string; w: number; h: number; alt: string; a?: string }
  | { sp: true; w: number; h: number }
  | { field: number; form: number; size: number; s: St; ph: string }
  | { btn: string; form: number; s: St }
export type Flow = { k: 't'; align: string; pre: boolean; runs: Run[] }
export type Box = {
  k: 'b'
  c: Node[]
  bg?: string
  pl?: number // CSS px of left indent
  mt?: number
  mb?: number
  w?: number // CSS px
  h?: number // CSS px, a minimum
  bar?: boolean // a blockquote's bar
  mark?: string // a list item's bullet or number
  // a table cell's
  span?: number
  wpct?: number
  align?: string
  m?: any // view.tsx's measure, cached
}
export type Row = { bg?: string; h?: number; cells: Box[] }
export type Table = { k: 'tab'; bg?: string; pad: number; full: boolean; border: boolean; rows: Row[]; m?: any }
export type Hr = { k: 'hr' }
export type Node = Box | Flow | Table | Hr
export type Field = { name: string; value: string; type: string }
export type Form = { action: string; fields: Field[] }
export type Page = {
  url: string
  title: string
  bg: string
  root: Box
  forms: Form[]
  truncated: boolean
  stats: { runs: number; images: number; links: number }
}

export type Options = { maxImages?: number; maxRuns?: number; sheets?: string[] }

const VOID = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr',
  'keygen', 'frame', 'basefont', 'isindex',
])
// Raw text: read to their end tag without looking for tags inside.
const RAW = new Set(['script', 'style', 'textarea', 'title', 'xmp', 'noscript', 'iframe', 'noembed', 'noframes', 'plaintext'])
// Junk: dropped with everything inside.
const SKIP = new Set([
  'script', 'style', 'noscript', 'template', 'iframe', 'object', 'embed', 'video', 'audio', 'canvas', 'svg', 'math',
  'select', 'datalist', 'map', 'noembed', 'noframes', 'frameset', 'head-skip', 'dialog', 'portal', 'slot',
])
const BLOCK = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'dd', 'details', 'dir', 'div', 'dl', 'dt', 'fieldset',
  'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'li', 'main',
  'menu', 'nav', 'ol', 'p', 'pre', 'section', 'summary', 'ul', 'legend', 'listing', 'xmp', 'search', 'caption',
])
// What closes an open <p>.
const P_CLOSERS = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'details', 'dir', 'div', 'dl', 'fieldset', 'figcaption',
  'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav',
  'ol', 'p', 'pre', 'section', 'table', 'ul', 'li', 'dd', 'dt', 'search', 'listing', 'xmp',
])
// Elements whose end tag a page may leave out, and what ends them then.
const OPTIONAL_END = new Set(['li', 'p', 'td', 'th', 'tr', 'dt', 'dd'])
const CLOSES: Record<string, string[]> = {
  li: ['li'], p: [...P_CLOSERS], td: ['td', 'th', 'tr'], th: ['td', 'th', 'tr'], tr: ['tr'], dt: ['dt', 'dd'],
  dd: ['dt', 'dd'],
}
const HEADING: Record<string, number> = { h1: 2, h2: 1.5, h3: 1.17, h4: 1, h5: 0.83, h6: 0.67 }
const FONT_SIZES = [0, 10, 13, 16, 18, 24, 32, 48]
// Vertical margins, in em of the element's own size.
const MARGIN: Record<string, number> = {
  p: 1, h1: 0.67, h2: 0.83, h3: 1, h4: 1.33, h5: 1.67, h6: 2.33, ul: 1, ol: 1, dl: 1, blockquote: 1, pre: 1,
  figure: 1, menu: 1, dir: 1, hr: 0.5, fieldset: 0.5,
}
const ENTITIES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', copy: '©', reg: '®', trade: '™', mdash: '—',
  ndash: '–', hellip: '…', laquo: '«', raquo: '»', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', sbquo: '‚',
  bdquo: '„', bull: '•', middot: '·', times: '×', divide: '÷', euro: '€', pound: '£', yen: '¥', cent: '¢',
  sect: '§', para: '¶', deg: '°', plusmn: '±', frac12: '½', frac14: '¼', frac34: '¾', sup2: '²', sup3: '³',
  larr: '←', rarr: '→', uarr: '↑', darr: '↓', harr: '↔', lArr: '⇐', rArr: '⇒', hearts: '♥', thinsp: ' ',
  ensp: ' ', emsp: ' ', zwnj: '', zwj: '', shy: '', lrm: '', rlm: '', iexcl: '¡', iquest: '¿',
  auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß', eacute: 'é', egrave: 'è',
  ecirc: 'ê', aacute: 'á', agrave: 'à', acirc: 'â', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ',
  ccedil: 'ç', aring: 'å', oslash: 'ø', aelig: 'æ', Eacute: 'É', prime: '′', Prime: '″', minus: '−', le: '≤',
  ge: '≥', ne: '≠', infin: '∞', check: '✓', star: '☆',
}

export function decode(text: string): string {
  if (text.indexOf('&') < 0) return text
  return text.replace(/&(#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[a-zA-Z][a-zA-Z0-9]{1,31})(;?)/g, (all, name, semi) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      if (!(code > 0) || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return '�'
      return String.fromCodePoint(code === 0xa0 ? 0xa0 : code)
    }
    const value = ENTITIES[name]
    if (value === undefined) return all
    // Without a ";" only the old ones, as browsers read them.
    if (!semi && !/^(amp|lt|gt|quot|nbsp|copy|reg)$/.test(name)) return all
    return value
  })
}

// A URL against the page's, or '' for one this browser does not open.
export function resolve(href: string, base: string): string {
  const h = href.trim().replace(/[\t\n\r]/g, '')
  if (!h || h[0] === '#') return ''
  if (/^(https?:|mailto:|tel:)/i.test(h)) return h
  if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return '' // javascript:, data:, ...
  const m = /^(https?:)\/\/([^/?#]*)([^?#]*)(\?[^#]*)?/i.exec(base)
  if (!m) return ''
  const [, scheme, host] = m
  const basePath = m[3] || '/'
  if (h.startsWith('//')) return scheme + h
  if (h[0] === '/') return scheme + '//' + host + normalizePath(h)
  if (h[0] === '?') return scheme + '//' + host + basePath + h
  const dir = basePath.slice(0, basePath.lastIndexOf('/') + 1)
  return scheme + '//' + host + normalizePath(dir + h)
}

function normalizePath(path: string): string {
  const q = path.search(/[?#]/)
  const p = q < 0 ? path : path.slice(0, q)
  const rest = q < 0 ? '' : path.slice(q)
  const out: string[] = []
  const parts = p.split('/')
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    if (part === '..') {
      if (out.length > 1) out.pop()
    } else if (part !== '.') out.push(part)
  }
  const last = parts[parts.length - 1]
  if ((last === '.' || last === '..') && out[out.length - 1] !== '') out.push('')
  return out.join('/') + rest
}

// The stylesheets a page links (the first few), and its <base href>.
export function scanHead(html: string, url: string): { base: string; sheets: string[] } {
  const head = html.slice(0, 200000)
  let base = url
  const b = /<base\s[^>]*href\s*=\s*["']?([^"' >]+)/i.exec(head)
  if (b) base = resolve(decode(b[1]), url) || url
  const sheets: string[] = []
  const re = /<link\s[^>]*>/gi
  let m: RegExpExecArray | null
  while ((m = re.exec(head)) && sheets.length < 3) {
    const tag = m[0]
    if (!/rel\s*=\s*["']?[^"'>]*\bstylesheet\b/i.test(tag)) continue
    if (/media\s*=\s*["']?(print|speech)/i.test(tag) || /\balternate\b/i.test(tag)) continue
    const href = /href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag)
    const abs = href ? resolve(decode(href[1] ?? href[2] ?? href[3] ?? ''), base) : ''
    if (abs && /^https?:/i.test(abs)) sheets.push(abs)
  }
  return { base, sheets }
}

type Kind = 'box' | 'table' | 'row' | 'inline' | 'form'
type Entry = {
  tag: string
  el: El
  st: St
  kind: Kind
  node?: Box | Table | Row
  flow?: Flow | null // a box's text flow still open
  href?: string
  form?: number // the GET form this is in, or -1 in a POST one
  list?: { ordered: boolean; n: number }
  btn?: { btn: string; form: number; s: St }
  apart?: boolean // an inline element with room after it (margin-right): words end there
}

const BASE_STYLE = { size: 16, color: '#000000', bold: false, italic: false, under: false, strike: false, mono: false,
  pre: false, align: '', hidden: false }

export function convert(html: string, url: string, options: Options = {}): Page {
  const maxImages = options.maxImages ?? 40
  const maxRuns = options.maxRuns ?? 30000
  const sheet: Sheet = newSheet()
  for (const css of options.sheets || []) addCss(sheet, css)
  const { base } = scanHead(html, url)

  const styles = new Map<string, St>()
  const intern = (s: Omit<St, 'key'>): St => {
    const key = `${Math.round(s.size * 10) / 10}|${s.color}|${+s.bold}${+s.italic}${+s.under}${+s.strike}${+s.mono}${+s.pre}${+s.hidden}|${s.align}`
    let st = styles.get(key)
    if (!st) styles.set(key, (st = { ...s, size: Math.round(s.size * 10) / 10, key }))
    return st
  }

  const root: Box = { k: 'b', c: [] }
  const page: Page = { url, title: '', bg: '', root, forms: [], truncated: false, stats: { runs: 0, images: 0, links: 0 } }
  const stack: Entry[] = [
    { tag: 'html', el: { tag: 'html', id: '', cls: [], link: false }, st: intern(BASE_STYLE), kind: 'box', node: root, flow: null, form: undefined },
  ]
  const els: El[] = [stack[0].el]
  let runs = 0

  const top = () => stack[stack.length - 1]
  const push = (e: Entry) => {
    stack.push(e)
    els.push(e.el)
  }
  const popTo = (i: number) => {
    // Pops entries i.. off the stack.
    while (stack.length > i && stack.length > 1) {
      stack.pop()
      els.pop()
    }
  }
  const find = (pred: (e: Entry) => boolean, stop?: (e: Entry) => boolean): number => {
    for (let i = stack.length - 1; i > 0; i--) {
      if (pred(stack[i])) return i
      if (stop && stop(stack[i])) return -1
    }
    return -1
  }
  const tableScope = (e: Entry) => e.kind === 'table' || e.kind === 'row' || e.tag === 'td' || e.tag === 'th'
  const formOf = (): number | undefined => {
    for (let i = stack.length - 1; i >= 0; i--) if (stack[i].form !== undefined) return stack[i].form
    return undefined
  }
  // The link text is in; a link around a block (<a><div>…</div></a>) still
  // links what is in it.
  const hrefOf = (): string => {
    for (let i = stack.length - 1; i > 0; i--) if (stack[i].href !== undefined) return stack[i].href as string
    return ''
  }

  // The box that text and inline things go into: the nearest open box, or a
  // cell made for them where a table holds them directly.
  const sinkEntry = (): Entry => {
    for (let i = stack.length - 1; i >= 0; i--) {
      const e = stack[i]
      if (e.kind === 'box') return e
      if (e.kind === 'table' || e.kind === 'row') {
        popTo(i + 1)
        if (e.kind === 'table') openRow(e, {}, e.st)
        return openCell(top(), 'td', {}, top().st, true)
      }
    }
    return stack[0]
  }
  const flowOf = (e: Entry): Flow => {
    if (!e.flow) {
      e.flow = { k: 't', align: e.st.align, pre: e.st.pre, runs: [] }
      ;(e.node as Box).c.push(e.flow)
    }
    return e.flow
  }
  const endFlow = () => {
    for (let i = stack.length - 1; i >= 0; i--) {
      if (stack[i].kind === 'box') {
        stack[i].flow = null
        return
      }
    }
  }
  const addRun = (run: Run) => {
    if (runs >= maxRuns) {
      page.truncated = true
      return
    }
    runs++
    flowOf(sinkEntry()).runs.push(run)
  }

  const text = (raw: string) => {
    const t = top()
    if (t.btn) {
      t.btn.btn = (t.btn.btn + decode(raw)).replace(/\s+/g, ' ')
      return
    }
    let s = decode(raw)
    if (!t.st.pre) {
      s = s.replace(/[ \t\n\r\f]+/g, ' ')
      if (s === ' ') {
        // White space alone between table parts is nothing.
        if (t.kind === 'table' || t.kind === 'row') return
      }
    } else {
      s = s.replace(/\r\n?/g, '\n')
    }
    if (!s || t.st.hidden) return
    const e = sinkEntry()
    const flow = flowOf(e)
    const last = flow.runs[flow.runs.length - 1] as any
    if (!t.st.pre && s[0] === ' ' && (!last || last.br || (last.x !== undefined && last.x.endsWith(' ')))) {
      s = s.slice(1)
      if (!s) return
    }
    if (t.st.pre && !last && s[0] === '\n') s = s.slice(1)
    const href = hrefOf()
    if (last && last.x !== undefined && last.s === t.st && (last.a || '') === href) {
      last.x += s
      return
    }
    const run: any = { x: s, s: t.st }
    if (href) {
      run.a = href
      page.stats.links++
    }
    addRun(run)
  }

  // The style an element gets: its parent's, the tag's own, its attributes,
  // the stylesheets' rules, then its style attribute.
  const styleFor = (tag: string, attrs: Record<string, string>, parent: St) => {
    const s: Omit<St, 'key'> = { ...parent }
    let bg = ''
    let display = BLOCK.has(tag) ? 'block' : ''
    let width = NaN
    let height = NaN
    let indent = NaN
    let apart = 0 // bit 1: room before it, bit 2: after it
    s.hidden = parent.hidden
    switch (tag) {
      case 'b':
      case 'strong':
      case 'th':
        s.bold = true
        break
      case 'i':
      case 'em':
      case 'cite':
      case 'var':
      case 'dfn':
      case 'address':
        s.italic = true
        break
      case 'u':
      case 'ins':
        s.under = true
        break
      case 's':
      case 'strike':
      case 'del':
        s.strike = true
        break
      case 'code':
      case 'kbd':
      case 'samp':
      case 'tt':
        s.mono = true
        break
      case 'pre':
      case 'xmp':
      case 'listing':
        s.mono = true
        s.pre = true
        break
      case 'small':
        s.size = parent.size / 1.2
        break
      case 'big':
        s.size = parent.size * 1.2
        break
      case 'sub':
      case 'sup':
        s.size = parent.size * 0.83
        break
      case 'center':
        s.align = 'center'
        break
      case 'a':
        if (attrs.href !== undefined) {
          s.color = '#0000ee'
          s.under = true
        }
        break
    }
    if (HEADING[tag]) {
      s.size = 16 * HEADING[tag] * (parent.size / 16)
      s.bold = true
    }
    if (tag === 'th') s.align = 'center'
    if (tag === 'font') {
      const c = colorOf(attrs.color)
      if (c) s.color = c
      const size = (attrs.size || '').trim()
      if (size) {
        let n = parseInt(size, 10)
        if (size[0] === '+' || size[0] === '-') n = 3 + n
        if (n > 0) s.size = FONT_SIZES[Math.min(7, Math.max(1, n))]
      }
    }
    if (attrs.align && /^(p|div|h[1-6]|td|th|tr|caption|center)$/.test(tag)) {
      const a = attrs.align.toLowerCase()
      s.align = a === 'center' || a === 'middle' ? 'center' : a === 'right' ? 'right' : a === 'left' ? '' : s.align
    }
    if (attrs.bgcolor) bg = colorOf(attrs.bgcolor)
    if (attrs.text && tag === 'body') s.color = colorOf(attrs.text) || s.color
    if (attrs.hidden !== undefined) display = 'none'
    if (attrs.width && /^\d+%$/.test(attrs.width.trim())) width = -parseInt(attrs.width, 10)
    else if (attrs.width && /^\d+(px)?$/.test(attrs.width.trim())) width = parseInt(attrs.width, 10)
    if (attrs.height && /^\d+(px)?$/.test(attrs.height.trim())) height = parseInt(attrs.height, 10)

    const apply = (d: Record<string, string>) => {
      if (d.color) s.color = colorOf(d.color) || s.color
      const b = backgroundOf(d['background-color'] || d.background)
      if (b) bg = b === 'transparent' ? '' : b
      if (d['font-size']) {
        const n = lengthOf(d['font-size'], parent.size)
        if (n > 0) s.size = n
      }
      if (d.font) {
        const m = /(^|\s)([\d.]+(?:px|pt|em|rem|%))/.exec(d.font)
        if (m) {
          const n = lengthOf(m[2], parent.size)
          if (n > 0) s.size = n
        }
        if (/\b(bold|[6-9]00)\b/.test(d.font)) s.bold = true
        if (/\bmonospace\b/.test(d.font)) s.mono = true
      }
      if (d['font-weight']) {
        const w = d['font-weight']
        s.bold = w === 'bold' || w === 'bolder' || parseInt(w, 10) >= 600
      }
      if (d['font-style']) s.italic = /italic|oblique/.test(d['font-style'])
      if (d['font-family']) s.mono = /monospace|courier|consolas|menlo|mono\b/i.test(d['font-family'])
      const deco = d['text-decoration-line'] || d['text-decoration']
      if (deco) {
        s.under = /underline/.test(deco)
        s.strike = /line-through/.test(deco)
      }
      if (d['text-align']) {
        const a = d['text-align']
        s.align = a === 'center' ? 'center' : a === 'right' || a === 'end' ? 'right' : ''
      }
      if (d.display) {
        const v = d.display.trim()
        if (v === 'none') display = 'none'
        else if (/^(block|flex|grid|list-item|flow-root|table)$/.test(v)) display = 'block'
        else if (/^(inline|inline-block|inline-flex|inline-grid|contents)$/.test(v)) display = ''
      }
      if (d.visibility) s.hidden = d.visibility === 'hidden' || d.visibility === 'collapse'
      if (d['white-space']) s.pre = /^pre/.test(d['white-space'])
      if (d.width) {
        const v = d.width.trim()
        if (/%$/.test(v)) width = -parseFloat(v)
        else {
          const n = lengthOf(v, s.size)
          if (n >= 0) width = n
        }
      }
      if (d.height) {
        const n = lengthOf(d.height, s.size)
        if (n >= 0) height = n
      }
      const ind = d['padding-left'] || d['margin-left']
      if (ind) {
        const n = lengthOf(ind, s.size)
        if (n >= 0) indent = n
        if (n >= 3) apart |= 1
      }
      const after = lengthOf(d['margin-right'] || d['padding-right'], s.size)
      if (after >= 3) apart |= 2
    }
    for (const d of matching(sheet, els)) apply(d)
    if (attrs.style) apply(parseDecls(attrs.style))
    return { st: intern(s), bg, display, width, height, indent, apart }
  }

  const openRow = (table: Entry, attrs: Record<string, string>, st: St, bg = '', height = NaN) => {
    const row: Row = { cells: [] }
    if (bg) row.bg = bg
    if (height > 0) row.h = height
    ;(table.node as Table).rows.push(row)
    push({ tag: 'tr', el: { tag: 'tr', id: '', cls: [], link: false }, st, kind: 'row', node: row })
  }
  const openCell = (row: Entry, tag: string, attrs: Record<string, string>, st: St, implicit = false,
    bg = '', width = NaN, height = NaN): Entry => {
    const cell: Box = { k: 'b', c: [] }
    const span = parseInt(attrs.colspan || '1', 10)
    if (span > 1) cell.span = Math.min(span, 50)
    if (bg) cell.bg = bg
    if (width > 0) cell.w = width
    else if (width < 0) cell.wpct = -width
    if (height > 0) cell.h = height
    ;(row.node as Row).cells.push(cell)
    const e: Entry = { tag, el: implicit ? { tag, id: '', cls: [], link: false } : row.el, st, kind: 'box', node: cell, flow: null }
    if (!implicit) e.el = { tag, id: '', cls: [], link: false }
    push(e)
    return e
  }

  let skip = '' // the tag a skipped subtree started with
  let skipDepth = 0

  const startTag = (tag: string, attrs: Record<string, string>, raw: string | null) => {
    if (skip) {
      // A hidden <li>, <p> or cell the page never closed ends at the next one.
      if (!(OPTIONAL_END.has(skip) && (tag === skip || CLOSES[skip]?.includes(tag)))) {
        if (tag === skip) skipDepth++
        return
      }
      skip = ''
    }
    if (SKIP.has(tag) || (tag === 'input' && (attrs.type || '').toLowerCase() === 'hidden')) {
      if (tag === 'input') {
        const form = formOf()
        if (form !== undefined && form >= 0 && attrs.name) {
          page.forms[form].fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'hidden' })
        }
        return
      }
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
      }
      return
    }
    if (tag === 'head' || tag === 'tbody' || tag === 'thead' || tag === 'tfoot' || tag === 'colgroup' || tag === 'col'
      || tag === 'meta' || tag === 'link' || tag === 'base' || tag === 'wbr' || tag === 'source' || tag === 'track'
      || tag === 'param' || tag === 'area' || tag === 'html' || tag === 'picture') {
      return
    }

    // The HTML rules that close what a page left open.
    if (P_CLOSERS.has(tag)) {
      const p = find((e) => e.tag === 'p', tableScope)
      if (p > 0) popTo(p)
    }
    if (tag === 'li') {
      const li = find((e) => e.tag === 'li', (e) => tableScope(e) || e.tag === 'ul' || e.tag === 'ol')
      if (li > 0) popTo(li)
    } else if (tag === 'dt' || tag === 'dd') {
      const d = find((e) => e.tag === 'dt' || e.tag === 'dd', (e) => tableScope(e) || e.tag === 'dl')
      if (d > 0) popTo(d)
    } else if (tag === 'a') {
      const a = find((e) => e.tag === 'a', tableScope)
      if (a > 0) popTo(a)
    } else if (HEADING[tag] && HEADING[top().tag]) {
      popTo(stack.length - 1)
    } else if (tag === 'button') {
      const b = find((e) => e.tag === 'button', tableScope)
      if (b > 0) popTo(b)
    }

    // Table parts go where their table is, whatever was left open in it.
    if (tag === 'tr') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    } else if (tag === 'td' || tag === 'th') {
      const r = find((e) => e.kind === 'row' || e.kind === 'table')
      if (r < 0) return
      popTo(r + 1)
      if (stack[r].kind === 'table') openRow(stack[r], {}, stack[r].st)
    } else if (tag === 'caption') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    }

    const parent = top()
    const el: El = {
      tag,
      id: attrs.id || '',
      cls: attrs.class ? attrs.class.trim().split(/\s+/) : [],
      link: tag === 'a' && attrs.href !== undefined,
    }
    els.push(el)
    const look = styleFor(tag, attrs, parent.st)
    els.pop()
    if (look.display === 'none') {
      if (!VOID.has(tag)) {
        skip = tag
        skipDepth = 1
      }
      return
    }
    const st = look.st
    // A form that posts (a login, a comment box) cannot be sent from here, and
    // a javascript: link does nothing without its script: both are dropped.
    if ((tag === 'form' && (attrs.method || '').toLowerCase() === 'post') ||
      (tag === 'a' && /^\s*javascript:/i.test(attrs.href || ''))) {
      skip = tag
      skipDepth = 1
      return
    }

    switch (tag) {
      case 'body': {
        if (look.bg) page.bg = look.bg
        stack[0].st = st
        stack[0].el = el
        els[0] = el
        return
      }
      case 'br':
        addRun({ br: true })
        return
      case 'hr': {
        const e = sinkEntry()
        e.flow = null
        ;(e.node as Box).c.push({ k: 'hr' })
        return
      }
      case 'img': {
        if (st.hidden) return
        let src = attrs.src || ''
        if ((!src || src.startsWith('data:')) && attrs['data-src']) src = attrs['data-src']
        const w = look.width >= 0 ? look.width : NaN
        const h = look.height >= 0 ? look.height : NaN
        const abs = src.startsWith('data:image/') ? src : resolve(decode(src), base)
        if ((w <= 2 && w >= 0) || (h <= 2 && h >= 0)) {
          // A spacer: Hacker News indents its comments with an empty picture.
          if (w > 2 || h > 2) addRun({ sp: true, w: w || 0, h: h || 0 })
          return
        }
        const alt = decode(attrs.alt || '').replace(/\s+/g, ' ').trim()
        const href = hrefOf()
        // An SVG is no picture a frame's <img> decodes (it sizes pictures as it
        // downloads them): its words instead.
        const svg = /\.svgz?(\?|#|$)/i.test(abs) || abs.startsWith('data:image/svg')
        if (!abs || svg || !/^(https?:|data:image\/)/.test(abs) || page.stats.images >= maxImages) {
          if (alt) text(alt)
          return
        }
        page.stats.images++
        const run: any = { img: abs, w: w || 0, h: h || 0, alt }
        if (href) run.a = href
        addRun(run)
        return
      }
      case 'input': {
        const type = (attrs.type || 'text').toLowerCase()
        const form = formOf()
        if (form === undefined || form < 0) return
        const f = page.forms[form]
        if (type === 'submit' || type === 'button' || type === 'image') {
          if (type === 'submit' || type === 'image') {
            if (attrs.name) f.fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'submit' })
            addRun({ btn: decode(attrs.value || attrs.alt || 'Submit'), form, s: st })
          }
          return
        }
        if (type === 'checkbox' || type === 'radio') {
          if (attrs.checked !== undefined && attrs.name) {
            f.fields.push({ name: attrs.name, value: decode(attrs.value || 'on'), type })
          }
          return
        }
        if (!/^(text|search|email|url|number|tel)$/.test(type) || !attrs.name) return
        f.fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'text' })
        const size = parseInt(attrs.size || '20', 10)
        addRun({ field: f.fields.length - 1, form, size: size > 0 ? Math.min(size, 80) : 20, s: st,
          ph: decode(attrs.placeholder || '') })
        return
      }
      case 'textarea': {
        const form = formOf()
        if (form === undefined || form < 0 || !attrs.name) return
        const f = page.forms[form]
        f.fields.push({ name: attrs.name, value: decode(raw || ''), type: 'text' })
        addRun({ field: f.fields.length - 1, form, size: 40, s: st, ph: decode(attrs.placeholder || '') })
        return
      }
    }
    if (VOID.has(tag)) return

    const e: Entry = { tag, el, st, kind: 'inline' }
    if (look.display !== 'block' && look.apart & 1) text(' ')
    if (look.display !== 'block' && look.apart & 2) e.apart = true
    if (tag === 'a' && attrs.href !== undefined) {
      e.href = resolve(decode(attrs.href), base)
    }
    if (tag === 'form') {
      const method = (attrs.method || 'get').toLowerCase()
      const action = resolve(decode(attrs.action || ''), base) || base
      if (method === 'get' && /^https?:/.test(action)) {
        page.forms.push({ action: action.replace(/[?#].*$/, ''), fields: [] })
        e.form = page.forms.length - 1
      } else {
        e.form = -1 // a dialog's form, or one to another scheme: its fields go
      }
      e.kind = 'form'
      endFlow()
      push(e)
      return
    }
    if (tag === 'button') {
      const form = formOf()
      const type = (attrs.type || 'submit').toLowerCase()
      if (form !== undefined && form >= 0 && type === 'submit') {
        const run = { btn: '', form, s: st }
        addRun(run)
        e.btn = run
      } else {
        e.st = intern({ ...st, hidden: true })
        e.btn = { btn: '', form: -1, s: st } // its words are no button's: dropped
      }
      push(e)
      return
    }
    if (tag === 'table') {
      // A table starts its text at the left, as a browser in quirks mode does
      // (inside a <center>, Hacker News's cells are not centered).
      e.st = intern({ ...st, align: '' })
      const sink = sinkEntry()
      sink.flow = null
      const pad = parseInt(attrs.cellpadding ?? '1', 10)
      const table: Table = { k: 'tab', pad: pad >= 0 ? Math.min(pad, 20) : 1, full: look.width === -100,
        border: parseInt(attrs.border || '0', 10) > 0, rows: [] }
      if (look.bg) table.bg = look.bg
      ;(sink.node as Box).c.push(table)
      e.kind = 'table'
      e.node = table
      push(e)
      return
    }
    if (tag === 'tr') {
      const t = stack[stack.length - 1]
      if (t.kind !== 'table') return
      openRow(t, attrs, st, look.bg, look.height)
      stack[stack.length - 1].el = el
      els[els.length - 1] = el
      return
    }
    if (tag === 'td' || tag === 'th') {
      const cell = openCell(top(), tag, attrs, st, false, look.bg, look.width, look.height)
      cell.el = el
      els[els.length - 1] = el
      if (st.align) (cell.node as Box).align = st.align
      return
    }
    if (tag === 'caption') {
      const t = top()
      openRow(t, {}, st)
      openCell(top(), 'td', { colspan: '50' }, intern({ ...st, align: 'center' }))
      top().el = el
      els[els.length - 1] = el
      return
    }
    if (look.display === 'block') {
      const sink = sinkEntry()
      sink.flow = null
      const box: Box = { k: 'b', c: [] }
      if (look.bg) box.bg = look.bg
      const m = MARGIN[tag]
      if (m) box.mt = box.mb = m * st.size
      if (tag === 'ul' || tag === 'ol' || tag === 'menu' || tag === 'dir') {
        box.pl = 28
        e.list = { ordered: tag === 'ol', n: parseInt(attrs.start || '1', 10) || 1 }
      }
      if (tag === 'dd') box.pl = 28
      if (tag === 'blockquote') {
        box.pl = 12
        box.bar = true
      }
      if (look.indent > 0 && look.indent < 200) box.pl = look.indent
      if (tag === 'li') {
        const list = find((x) => !!x.list, tableScope)
        if (list > 0) {
          const l = stack[list].list as { ordered: boolean; n: number }
          box.mark = l.ordered ? `${l.n++}.` : '•'
        } else box.mark = '•'
      }
      if (look.width > 0) box.w = look.width
      if (look.height > 0 && look.height < 2000) box.h = look.height
      if (tag === 'pre') box.bg = box.bg || '#f3f3f3'
      ;(sink.node as Box).c.push(box)
      e.kind = 'box'
      e.node = box
      e.flow = null
    }
    push(e)
  }

  const endTag = (tag: string) => {
    if (skip) {
      if (tag === skip) {
        if (--skipDepth === 0) skip = ''
        return
      }
      // A hidden <li> or <td> the page never closed ends with its list.
      if (!OPTIONAL_END.has(skip) || find((e) => e.tag === tag) <= 0) return
      skip = ''
    }
    if (tag === 'br') {
      addRun({ br: true })
      return
    }
    if (tag === 'body' || tag === 'html' || tag === 'head') return
    const tableTag = tag === 'table' || tag === 'tr' || tag === 'td' || tag === 'th' || tag === 'caption'
    const i = find(
      (e) => e.tag === tag,
      tableTag ? (e) => e.kind === 'table' && tag !== 'table' : tableScope
    )
    if (i <= 0) return
    const closing = stack[i]
    popTo(i)
    if (closing.kind === 'box' || closing.kind === 'table' || closing.kind === 'form') endFlow()
    else if (closing.apart) text(' ')
  }

  // The tokenizer.
  const n = html.length
  let i = 0
  while (i < n) {
    const lt = html.indexOf('<', i)
    if (lt < 0) {
      if (!skip) text(html.slice(i))
      break
    }
    if (lt > i && !skip) text(html.slice(i, lt))
    i = lt
    const c = html.charCodeAt(i + 1)
    if (html.startsWith('<!--', i)) {
      const end = html.indexOf('-->', i + 4)
      i = end < 0 ? n : end + 3
      continue
    }
    if (c === 33 /* ! */ || c === 63 /* ? */) {
      const end = html.indexOf('>', i)
      i = end < 0 ? n : end + 1
      continue
    }
    const closing = c === 47 /* / */
    const nameStart = closing ? i + 2 : i + 1
    let j = nameStart
    while (j < n) {
      const ch = html.charCodeAt(j)
      if ((ch >= 97 && ch <= 122) || (ch >= 65 && ch <= 90) || (ch >= 48 && ch <= 57 && j > nameStart) || ch === 45 || ch === 58) j++
      else break
    }
    if (j === nameStart) {
      if (!skip) text('<')
      i++
      continue
    }
    const tag = html.slice(nameStart, j).toLowerCase()
    // The attributes, to the tag's ">" (one inside quotes does not end it).
    const attrs: Record<string, string> = {}
    let k = j
    while (k < n) {
      const ch = html[k]
      if (ch === '>') break
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '/') {
        k++
        continue
      }
      let e = k
      while (e < n && !/[\s=>/]/.test(html[e])) e++
      const name = html.slice(k, e).toLowerCase()
      k = e
      while (k < n && /\s/.test(html[k])) k++
      let value = ''
      if (html[k] === '=') {
        k++
        while (k < n && /\s/.test(html[k])) k++
        const q = html[k]
        if (q === '"' || q === "'") {
          const end = html.indexOf(q, k + 1)
          value = html.slice(k + 1, end < 0 ? n : end)
          k = end < 0 ? n : end + 1
        } else {
          let e2 = k
          while (e2 < n && !/[\s>]/.test(html[e2])) e2++
          value = html.slice(k, e2)
          k = e2
        }
      }
      if (name && !(name in attrs)) attrs[name] = value
    }
    i = k + 1
    if (closing) {
      endTag(tag)
      continue
    }
    let raw: string | null = null
    if (RAW.has(tag)) {
      const end = findClose(html, tag, i)
      raw = html.slice(i, end)
      const gt = html.indexOf('>', end)
      i = gt < 0 ? n : gt + 1
      if (tag === 'plaintext') i = n
    }
    if (raw !== null && tag !== 'textarea') {
      // Raw text: a title or a style sheet is kept, the rest is junk.
      if (skip) continue
      if (tag === 'title' && !page.title) page.title = decode(raw).replace(/\s+/g, ' ').trim()
      else if (tag === 'style') addCss(sheet, raw)
      continue
    }
    startTag(tag, attrs, raw)
    if (runs >= maxRuns) {
      page.truncated = true
      break
    }
  }

  page.stats.runs = runs
  cleanBox(root)
  return page
}

function findClose(html: string, tag: string, from: number): number {
  const re = new RegExp('</' + tag + '[\\s>/]', 'ig')
  re.lastIndex = from
  const m = re.exec(html)
  return m ? m.index : html.length
}

// Trims each flow and drops what shows nothing; a box around one box and
// nothing else of its own becomes that box; a table of one column becomes the
// boxes of its rows. Keeps the tree shallow for the layout's depth limit.
function hasText(flow: Flow): boolean {
  for (const r of flow.runs as any[]) {
    if (r.x !== undefined ? r.x.trim() !== '' && !r.s.hidden : !r.br) return true
  }
  return false
}

function cleanFlow(flow: Flow): Flow | null {
  const runs = flow.runs as any[]
  while (runs.length && runs[runs.length - 1].br) runs.pop()
  const last = runs[runs.length - 1]
  if (last && last.x !== undefined && !flow.pre) last.x = last.x.replace(/ +$/, '')
  return hasText(flow) ? flow : null
}

function plain(box: Box): boolean {
  return !box.bg && !box.pl && !box.w && !box.h && !box.bar && !box.mark && !box.span && !box.wpct && !box.align
}

export function cleanBox(box: Box): Box | null {
  const out: Node[] = []
  for (const child of box.c) {
    let c: Node | null = child
    if (child.k === 't') c = cleanFlow(child)
    else if (child.k === 'b') c = cleanBox(child)
    else if (child.k === 'tab') c = cleanTable(child)
    if (!c) continue
    if (c.k === 'b' && plain(c) && !c.mt && !c.mb) {
      // A plain wrapper inside a box: its children are the box's.
      for (const g of c.c) out.push(g)
    } else out.push(c)
  }
  box.c = out
  if (!out.length && !box.h && !box.span && !box.w) return null
  if (out.length === 1 && out[0].k === 'b' && plain(box)) {
    const only = out[0] as Box
    only.mt = Math.max(only.mt || 0, box.mt || 0) || undefined
    only.mb = Math.max(only.mb || 0, box.mb || 0) || undefined
    return only
  }
  return box
}

function cleanTable(table: Table): Node | null {
  const rows: Row[] = []
  let cols = 0
  for (const row of table.rows) {
    const cells: Box[] = []
    let any = false
    for (const cell of row.cells) {
      // The cell stays (its width and span), with what it holds cleaned.
      cleanBox(cell)
      if (cell.c.length) any = true
      cells.push(cell)
    }
    if (!any && !row.h) continue
    if (!any) {
      rows.push({ h: row.h, bg: row.bg, cells: [] })
      continue
    }
    let width = 0
    for (const cell of cells) width += cell.span || 1
    cols = Math.max(cols, width)
    rows.push({ bg: row.bg, h: row.h, cells })
  }
  if (!rows.length) return null
  if (cols <= 1) {
    // One column: its rows, one under another.
    const box: Box = { k: 'b', c: [] }
    if (table.bg) box.bg = table.bg
    for (const row of rows) {
      if (!row.cells.length) {
        box.c.push({ k: 'b', c: [], h: row.h })
        continue
      }
      const cell = row.cells.find((c) => c.c.length) as Box
      if (!cell.bg && row.bg) cell.bg = row.bg
      if (!cell.h && row.h) cell.h = row.h
      cell.span = undefined
      cell.wpct = undefined
      if (!cell.bg && !cell.h && !cell.align && !cell.w) {
        for (const g of cell.c) box.c.push(g)
      } else box.c.push(cell)
    }
    return cleanBox(box)
  }
  table.rows = rows
  return table
}

sources.css.ts:
// A small cascade: the rules of a page's stylesheets and <style> blocks, read
// for the few properties this browser draws (colors, sizes, weight, slant,
// decoration, alignment, what is hidden, white space, a cell's width and a
// row's height). Selectors are tags, classes, ids, `*` and `:link`, joined by
// descendant (`a b`) or child (`a > b`, read as descendant) combinators;
// anything else (attributes, `:hover`, siblings) is a rule that never applies,
// and @media, @supports and the like are skipped whole. That is enough for
// Hacker News, and for the hidden and colored parts of most pages.

export type Decl = Record<string, string>
// One compound selector: a tag, an id, classes, and :link.
type Part = { tag: string; id: string; cls: string[]; link: boolean }
export type Rule = { parts: Part[]; spec: number; order: number; decl: Decl }
// What a selector is matched against: an element on the open stack.
export type El = { tag: string; id: string; cls: string[]; link: boolean }
export type Sheet = { byKey: Map<string, Rule[]>; count: number }

const MAX_RULES = 3000
const MAX_TEXT = 256 * 1024
// The properties anything here reads; the rest are not kept.
const KEPT = new Set([
  'color',
  'background',
  'background-color',
  'font-size',
  'font-weight',
  'font-style',
  'font-family',
  'font',
  'text-decoration',
  'text-decoration-line',
  'text-align',
  'display',
  'visibility',
  'white-space',
  'width',
  'height',
  'padding-left',
  'padding-right',
  'margin-left',
  'margin-right',
])

export function newSheet(): Sheet {
  return { byKey: new Map(), count: 0 }
}

function parsePart(text: string): Part | null {
  const m = /^([a-z][a-z0-9-]*|\*)?((?:[.#][\w-]+)*)(:link)?$/i.exec(text)
  if (!m || (!m[1] && !m[2] && !m[3])) return null
  const part: Part = { tag: m[1] && m[1] !== '*' ? m[1].toLowerCase() : '', id: '', cls: [], link: !!m[3] }
  const bits = m[2] ? m[2].match(/[.#][\w-]+/g) || [] : []
  for (const bit of bits) {
    if (bit[0] === '#') part.id = bit.slice(1)
    else part.cls.push(bit.slice(1))
  }
  return part
}

function parseSelector(text: string): { parts: Part[]; spec: number } | null {
  const words = text.replace(/\s*>\s*/g, ' ').trim().split(/\s+/)
  const parts: Part[] = []
  let spec = 0
  for (const word of words) {
    const part = parsePart(word)
    if (!part) return null
    spec += (part.id ? 10000 : 0) + (part.cls.length + (part.link ? 1 : 0)) * 100 + (part.tag ? 1 : 0)
    parts.push(part)
  }
  return parts.length ? { parts, spec } : null
}

export function parseDecls(text: string): Decl {
  const decl: Decl = {}
  for (const item of text.split(';')) {
    const at = item.indexOf(':')
    if (at < 0) continue
    const name = item.slice(0, at).trim().toLowerCase()
    if (!KEPT.has(name)) continue
    const value = item
      .slice(at + 1)
      .replace(/!\s*important/i, '')
      .trim()
    if (value) decl[name] = value
  }
  return decl
}

// Where a block that starts at `at` (just past its "{") ends.
function blockEnd(text: string, at: number): number {
  let depth = 1
  for (let i = at; i < text.length; i++) {
    const c = text[i]
    if (c === '{') depth++
    else if (c === '}' && --depth === 0) return i
  }
  return text.length
}

export function addCss(sheet: Sheet, source: string) {
  const text = source.slice(0, MAX_TEXT).replace(/\/\*[\s\S]*?(\*\/|$)/g, '')
  let at = 0
  while (at < text.length && sheet.count < MAX_RULES) {
    const open = text.indexOf('{', at)
    if (open < 0) break
    let head = text.slice(at, open).trim()
    // A statement at-rule (@import, @charset) before it ends at its ";".
    while (head[0] === '@' && head.indexOf(';') >= 0 && head.indexOf(';') < head.length - 1) {
      head = head.slice(head.indexOf(';') + 1).trim()
    }
    const close = blockEnd(text, open + 1)
    if (head[0] !== '@') {
      const decl = parseDecls(text.slice(open + 1, close))
      if (Object.keys(decl).length) {
        for (const selText of head.split(',')) {
          const sel = parseSelector(selText)
          if (!sel) continue
          const last = sel.parts[sel.parts.length - 1]
          const key = last.id ? '#' + last.id : last.cls.length ? '.' + last.cls[0] : last.tag || '*'
          const list = sheet.byKey.get(key)
          const rule = { parts: sel.parts, spec: sel.spec, order: sheet.count++, decl }
          if (list) list.push(rule)
          else sheet.byKey.set(key, [rule])
        }
      }
    }
    at = close + 1
  }
}

function partMatches(part: Part, el: El): boolean {
  if (part.tag && part.tag !== el.tag) return false
  if (part.id && part.id !== el.id) return false
  if (part.link && !el.link) return false
  for (const c of part.cls) if (el.cls.indexOf(c) < 0) return false
  return true
}

// Whether a rule's selector matches the element on top of `stack`.
function matches(rule: Rule, stack: El[]): boolean {
  const parts = rule.parts
  let p = parts.length - 1
  if (!partMatches(parts[p], stack[stack.length - 1])) return false
  p--
  for (let i = stack.length - 2; i >= 0 && p >= 0; i--) {
    if (partMatches(parts[p], stack[i])) p--
  }
  return p < 0
}

// The declarations that apply to the element on top of `stack`, the more
// specific (then the later) last, so a plain loop over them cascades.
export function matching(sheet: Sheet, stack: El[]): Decl[] {
  if (!sheet.count) return []
  const el = stack[stack.length - 1]
  const found: Rule[] = []
  const take = (key: string) => {
    const list = sheet.byKey.get(key)
    if (list) for (const rule of list) if (found.indexOf(rule) < 0 && matches(rule, stack)) found.push(rule)
  }
  if (el.id) take('#' + el.id)
  for (const c of el.cls) take('.' + c)
  take(el.tag)
  take('*')
  found.sort((a, b) => a.spec - b.spec || a.order - b.order)
  return found.map((r) => r.decl)
}

const NAMED = new Set([
  'black', 'white', 'red', 'green', 'blue', 'gray', 'grey', 'silver', 'maroon', 'navy', 'purple', 'teal', 'olive',
  'orange', 'yellow', 'lime', 'aqua', 'fuchsia', 'brown', 'pink', 'gold', 'darkgray', 'darkgrey', 'lightgray',
  'lightgrey', 'dimgray', 'dimgrey', 'darkblue', 'darkred', 'darkgreen', 'whitesmoke', 'gainsboro', 'beige', 'ivory',
  'tomato', 'crimson', 'indigo', 'violet', 'coral', 'salmon', 'khaki', 'tan', 'steelblue', 'royalblue', 'slategray',
])

// A color the UI can draw, as Tailwind's bracket takes it, or '' for none.
export function colorOf(value: string | undefined): string {
  if (!value) return ''
  const v = value.trim().toLowerCase()
  if (/^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/.test(v)) return v
  if (/^[0-9a-f]{6}$/.test(v)) return '#' + v // <font color="ff6600">
  if (/^rgba?\([\d.,%\s/]+\)$/.test(v)) return v.replace(/\s*\/\s*/, ',').replace(/\s+/g, ',').replace(/,+/g, ',')
  if (NAMED.has(v)) return v
  return ''
}

// The first color in a `background` shorthand.
export function backgroundOf(value: string | undefined): string {
  if (!value) return ''
  if (/^(none|transparent)$/i.test(value.trim())) return 'transparent'
  const m = /(#[0-9a-f]{3,8}\b|rgba?\([^)]*\))/i.exec(value)
  if (m) return colorOf(m[1])
  for (const word of value.split(/\s+/)) {
    const c = colorOf(word)
    if (c) return c
  }
  return ''
}

const KEYWORD_SIZES: Record<string, number> = {
  'xx-small': 9,
  'x-small': 10,
  small: 13,
  medium: 16,
  large: 18,
  'x-large': 24,
  'xx-large': 32,
}

// A length in CSS pixels; `of` is what % and em are of. NaN for what is not one.
export function lengthOf(value: string | undefined, of: number): number {
  if (!value) return NaN
  const v = value.trim().toLowerCase()
  if (v in KEYWORD_SIZES) return KEYWORD_SIZES[v]
  if (v === 'smaller') return of / 1.2
  if (v === 'larger') return of * 1.2
  const m = /^(-?[\d.]+)(px|pt|em|rem|%|ex|ch|vw|vh)?$/.exec(v)
  if (!m) return NaN
  const n = parseFloat(m[1])
  switch (m[2]) {
    case 'pt':
      return (n * 4) / 3
    case 'em':
      return n * of
    case 'rem':
      return n * 16
    case 'ex':
    case 'ch':
      return n * of * 0.5
    case '%':
      return (n * of) / 100
    case 'vw':
    case 'vh':
      return NaN
    default:
      return n
  }
}

sources.view.tsx:
// A page (html.ts) as JSX. Text that holds no link is a block of spans and
// wraps as text does; text with links in it is a wrapping row of its words,
// each word an element, so a link's every word takes a tap (a handler on a
// span inside running text is not one the layout hit-tests, docs/jsx-ui.md).
// Tables get column widths the way a browser's automatic layout picks them,
// from what each column holds at its narrowest and at its widest.

import type { Box, Flow, Node, Page, Row, Run, St, Table } from './html'

export type Look = {
  k: number // UI pixels per CSS pixel
  minPx: number // the smallest text
  ink: boolean // black on white: e-paper, a panel without color
}
export type Act = {
  go(url: string): void
  hold(url: string): void
  value(form: number, field: number): string
  type(form: number, field: number, value: string): void
  submit(form: number): void
}

const LEADING = 1.3

// What a style looks like at a scale, as classes, and how wide its letters are.
type Face = { cls: string; px: number; lh: number; ch: number }
let faces = new Map<string, Face>()
let facesFor = ''

function face(s: St, look: Look): Face {
  let f = faces.get(s.key)
  if (f) return f
  const px = Math.max(look.minPx, Math.round(s.size * look.k))
  const lh = Math.round(px * LEADING)
  let cls = `text-[${px}px] leading-[${lh}px]`
  const color = look.ink ? '#000000' : s.color
  if (color) cls += ` text-[${color}]`
  if (s.bold) cls += ' font-bold'
  if (s.italic) cls += ' italic'
  if (s.under) cls += ' underline'
  if (s.strike) cls += ' line-through'
  if (s.mono) cls += ' font-mono'
  f = { cls, px, lh, ch: px * (s.mono ? 0.6 : 0.53) * (s.bold ? 1.07 : 1) }
  faces.set(s.key, f)
  return f
}

const bgOf = (color: string | undefined, look: Look) =>
  !color || color === 'transparent' ? '' : look.ink ? (dark(color) ? 'bg-[#000000]' : '') : `bg-[${color}]`

function dark(color: string): boolean {
  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})/.exec(color)
  if (!m) return color === 'black' || color === 'navy'
  return parseInt(m[1], 16) * 0.3 + parseInt(m[2], 16) * 0.59 + parseInt(m[3], 16) * 0.11 < 90
}

const px = (css: number, look: Look) => Math.round(css * look.k)
const alignCls = (a: string) => (a === 'center' ? 'text-center' : a === 'right' ? 'text-right' : '')
const justifyCls = (a: string) => (a === 'center' ? 'justify-center' : a === 'right' ? 'justify-end' : '')

// --- How wide things are: [narrowest, widest], in UI pixels.

function imgSize(r: { w: number; h: number }, look: Look): [number, number] {
  let w = r.w ? px(r.w, look) : 0
  let h = r.h ? px(r.h, look) : 0
  if (!w && !h) w = Math.round(160 * look.k)
  return [w, h]
}

function measureFlow(flow: Flow, look: Look): [number, number] {
  let min = 0
  let max = 0
  let line = 0
  for (const r of flow.runs as any[]) {
    if (r.x !== undefined) {
      const f = face(r.s, look)
      const words = flow.pre ? r.x.split('\n') : r.x.split(' ')
      for (let i = 0; i < words.length; i++) {
        if (i > 0) {
          if (flow.pre) line = 0
          else line += f.ch
        }
        const w = words[i].length * f.ch
        line += w
        if (w > min) min = flow.pre ? line : w
        if (line > max) max = line
      }
    } else if (r.br) {
      line = 0
    } else {
      const w = r.img ? imgSize(r, look)[0] : r.sp ? px(r.w, look) : r.field !== undefined
        ? Math.min(r.size, 30) * face(r.s, look).ch : r.btn !== undefined ? (r.btn.length + 2) * face(r.s, look).ch : 0
      line += w
      if (w > min) min = w
      if (line > max) max = line
    }
  }
  return [Math.ceil(min), Math.ceil(max)]
}

function measure(node: Node, look: Look): [number, number] {
  if (node.k === 't') return measureFlow(node, look)
  if (node.k === 'hr') return [0, 0]
  const cached = (node as any).m
  if (cached && cached.k === look.k) return cached.v
  let v: [number, number]
  if (node.k === 'tab') {
    const cols = colRange(node, look)
    v = [cols.min.reduce((a, b) => a + b, 0), cols.max.reduce((a, b) => a + b, 0)]
  } else {
    let min = 0
    let max = 0
    for (const c of node.c) {
      const [a, b] = measure(c, look)
      if (a > min) min = a
      if (b > max) max = b
    }
    const extra = px(node.pl || 0, look) + (node.mark ? markWidth(look) : 0) + (node.bar ? 4 : 0)
    min += extra
    max += extra
    if (node.w) {
      const w = px(node.w, look)
      min = Math.max(min, Math.min(w, min || w))
      max = Math.max(min, w)
    }
    v = [min, max]
  }
  ;(node as any).m = { k: look.k, v }
  return v
}

const markWidth = (look: Look) => Math.round(22 * look.k)

// A table's columns at their narrowest and widest (cell padding included).
function colRange(table: Table, look: Look) {
  const cached = (table as any).cr
  if (cached && cached.k === look.k) return cached
  let count = 0
  for (const row of table.rows) {
    let n = 0
    for (const cell of row.cells) n += cell.span || 1
    if (n > count) count = n
  }
  const min = new Array(count).fill(0)
  const max = new Array(count).fill(0)
  const fixed = new Array(count).fill(0)
  const pad = px(table.pad, look) * 2
  const spans: [number, number, number, number][] = []
  for (const row of table.rows) {
    let col = 0
    for (const cell of row.cells) {
      const span = cell.span || 1
      const [a, b] = measure(cell, look)
      if (span === 1) {
        if (a + pad > min[col]) min[col] = a + pad
        if (b + pad > max[col]) max[col] = b + pad
        if (cell.w) fixed[col] = Math.max(fixed[col], px(cell.w, look) + pad)
      } else spans.push([col, Math.min(span, count - col), a + pad, b + pad])
      col += span
    }
  }
  for (let c = 0; c < count; c++) {
    if (fixed[c]) {
      min[c] = Math.max(min[c], fixed[c])
      max[c] = min[c]
    }
  }
  // A cell across columns that is wider than they are widens them evenly.
  for (const [col, span, a, b] of spans) {
    let sa = 0
    let sb = 0
    for (let c = col; c < col + span; c++) {
      sa += min[c]
      sb += max[c]
    }
    for (let c = col; c < col + span; c++) {
      if (a > sa) min[c] += (a - sa) / span
      if (b > sb && !fixed[c]) max[c] += (b - sb) / span
      if (max[c] < min[c]) max[c] = min[c]
    }
  }
  const range = { k: look.k, min, max, fixed }
  ;(table as any).cr = range
  return range
}

// Column widths for a table given `width` UI pixels.
function columns(table: Table, width: number, look: Look): number[] {
  const cached = (table as any).cw
  if (cached && cached.k === look.k && cached.width === width) return cached.v
  const { min, max, fixed } = colRange(table, look)
  const sumMin = min.reduce((a: number, b: number) => a + b, 0)
  const sumMax = max.reduce((a: number, b: number) => a + b, 0)
  const target = table.full ? width : Math.min(width, sumMax)
  let v: number[]
  if (sumMax <= target) {
    v = max.slice()
    const loose = max.reduce((a: number, b: number, i: number) => a + (fixed[i] ? 0 : b), 0)
    if (target > sumMax && loose > 0) v = v.map((w, i) => (fixed[i] ? w : w + ((target - sumMax) * w) / loose))
  } else if (sumMin >= target) {
    v = min.map((w: number) => (w * target) / Math.max(1, sumMin))
  } else {
    const t = (target - sumMin) / Math.max(1, sumMax - sumMin)
    v = min.map((w: number, i: number) => w + (max[i] - w) * t)
  }
  v = v.map((w) => Math.floor(w))
  ;(table as any).cw = { k: look.k, width, v }
  return v
}

// --- Drawing.

function firstStyle(runs: Run[]): St | null {
  for (const r of runs as any[]) if (r.s) return r.s
  return null
}

type Ctx = { look: Look; act: Act; links: Map<string, { click: () => void; hold: () => void }> }

function linkHandlers(ctx: Ctx, url: string) {
  let h = ctx.links.get(url)
  if (!h) {
    h = { click: () => ctx.act.go(url), hold: () => ctx.act.hold(url) }
    ctx.links.set(url, h)
  }
  return h
}

function piece(ctx: Ctx, p: { x: string; s: St; a?: string }) {
  const f = face(p.s, ctx.look)
  if (!p.a) return <span className={f.cls}>{p.x}</span>
  if (!/^https?:/.test(p.a)) {
    // mailto: and tel: open as the frame opens links: a QR code to scan.
    return (
      <a href={p.a} className={f.cls}>
        {p.x}
      </a>
    )
  }
  const h = linkHandlers(ctx, p.a)
  return (
    <a className={`${f.cls} cursor-pointer`} onClick={h.click} onLongPress={h.hold}>
      {p.x}
    </a>
  )
}

function runItem(ctx: Ctx, r: any, width: number) {
  const look = ctx.look
  if (r.img) {
    let [w, h] = imgSize(r, look)
    if (w > width) {
      if (h) h = Math.round((h * width) / w)
      w = width
    }
    const img = <img src={r.img} className={`${w ? `w-[${w}px]` : ''} ${h ? `h-[${h}px]` : ''} object-contain shrink-0`} />
    if (!r.a || !/^https?:/.test(r.a)) return img
    const handlers = linkHandlers(ctx, r.a)
    return (
      <div className="flex shrink-0 cursor-pointer" onClick={handlers.click} onLongPress={handlers.hold}>
        {img}
      </div>
    )
  }
  if (r.sp) return <div className={`shrink-0 w-[${Math.min(width, px(r.w, look))}px] h-[${px(r.h, look)}px]`} />
  const f = face(r.s, look)
  if (r.field !== undefined) {
    const w = Math.min(width, Math.max(Math.round(f.ch * Math.min(r.size, 40) + f.px), Math.round(f.px * 6)))
    return (
      <input
        className={`w-[${w}px] h-[${f.lh + 8}px] px-[4px] border border-[#999999] bg-[#ffffff] text-[#000000] text-[${f.px}px]`}
        value={ctx.act.value(r.form, r.field)}
        placeholder={r.ph}
        onChange={(e: any) => ctx.act.type(r.form, r.field, String(e.target.value))}
        onKeyDown={(e: any) => {
          if (e.key === 'Enter') ctx.act.submit(r.form)
        }}
      />
    )
  }
  if (r.btn !== undefined) {
    return (
      <div
        className={`px-[8px] h-[${f.lh + 8}px] flex items-center rounded border border-[#999999] bg-[#eeeeee] text-[#000000] text-[${f.px}px] cursor-pointer`}
        onClick={() => ctx.act.submit(r.form)}
      >
        {r.btn.trim() || 'Submit'}
      </div>
    )
  }
  return null
}

function renderFlow(ctx: Ctx, flow: Flow, width: number) {
  const look = ctx.look
  const runs = flow.runs as any[]
  if (flow.pre) return renderPre(ctx, flow)
  let interactive = false
  for (const r of runs) {
    if (r.x === undefined ? !r.br : !!r.a) {
      interactive = true
      break
    }
  }
  if (!interactive) {
    // Text and line breaks: a block of spans, wrapped by the layout.
    const first = runs.find((r) => r.x !== undefined)
    const same = runs.every((r) => r.br || r.s === first.s)
    const f = face(first.s, look)
    if (same) {
      const parts: any[] = []
      for (const r of runs) parts.push(r.br ? <br /> : r.x)
      return <div className={`${f.cls} ${alignCls(flow.align)}`}>{parts}</div>
    }
    return (
      <div className={`leading-[${f.lh}px] ${alignCls(flow.align)}`}>
        {runs.map((r) => (r.br ? <br /> : <span className={face(r.s, look).cls}>{r.x}</span>))}
      </div>
    )
  }
  // Words in a wrapping row: a word is one element, or a row of the pieces of
  // it that differ (a link inside parentheses).
  const items: any[] = []
  let word: { x: string; s: St; a?: string }[] = []
  let gap = 0
  const end = () => {
    if (word.length === 1) items.push(piece(ctx, word[0]))
    else if (word.length > 1) items.push(<div className="flex items-end">{word.map((p) => piece(ctx, p))}</div>)
    word = []
  }
  let lastBr = true
  for (const r of runs) {
    if (r.x !== undefined) {
      if (!gap) gap = Math.max(2, Math.round(face(r.s, look).px * 0.28))
      const parts = r.x.split(' ')
      for (let i = 0; i < parts.length; i++) {
        if (i > 0) end()
        if (parts[i]) {
          const last = word[word.length - 1]
          if (last && last.s === r.s && last.a === r.a) last.x += parts[i]
          else word.push({ x: parts[i], s: r.s, a: r.a })
          lastBr = false
        }
      }
    } else if (r.br) {
      end()
      // A line break is an item a line wide; a second one is an empty line.
      const st = firstStyle(runs)
      items.push(<div className={`basis-full ${lastBr && st ? `h-[${face(st, look).lh}px]` : 'h-0'}`} />)
      lastBr = true
    } else {
      end()
      items.push(runItem(ctx, r, width))
      lastBr = false
    }
  }
  end()
  return <div className={`flex flex-wrap items-end gap-x-[${gap || 4}px] ${justifyCls(flow.align)}`}>{items}</div>
}

// Preformatted text, a line an element, its spaces kept (no-break spaces,
// which the layout does not fold), scrolled sideways when it is wider.
function renderPre(ctx: Ctx, flow: Flow) {
  const lines: any[] = []
  let line: any[] = []
  const end = () => {
    lines.push(<div className="whitespace-nowrap flex">{line.length ? line : ' '}</div>)
    line = []
  }
  for (const r of flow.runs as any[]) {
    if (r.br) {
      end()
      continue
    }
    if (r.x === undefined) continue
    const parts = r.x.replace(/\t/g, '    ').split('\n')
    for (let i = 0; i < parts.length; i++) {
      if (i > 0) end()
      if (parts[i]) line.push(piece(ctx, { x: parts[i].replace(/ /g, ' '), s: r.s, a: r.a }))
    }
  }
  if (line.length) end()
  return <div className="flex flex-col overflow-x-auto">{lines}</div>
}

function renderTable(ctx: Ctx, table: Table, width: number) {
  const look = ctx.look
  const cols = columns(table, width, look)
  const total = cols.reduce((a, b) => a + b, 0)
  const pad = px(table.pad, look)
  const rows: any[] = []
  for (const row of table.rows) rows.push(renderRow(ctx, table, row, cols, pad))
  return (
    <div className={`flex flex-col shrink-0 w-[${Math.min(width, total)}px] ${bgOf(table.bg, look)}`}>{rows}</div>
  )
}

function renderRow(ctx: Ctx, table: Table, row: Row, cols: number[], pad: number) {
  const look = ctx.look
  if (!row.cells.length) return <div className={`h-[${px(row.h || 0, look)}px] ${bgOf(row.bg, look)}`} />
  const cells: any[] = []
  let col = 0
  for (const cell of row.cells) {
    const span = cell.span || 1
    let w = 0
    for (let c = col; c < Math.min(cols.length, col + span); c++) w += cols[c]
    col += span
    const inner = w - pad * 2
    cells.push(
      <div
        className={`flex flex-col shrink-0 w-[${w}px] ${pad ? `p-[${pad}px]` : ''} ${bgOf(cell.bg, look)} ${
          cell.h ? `min-h-[${px(cell.h, look)}px]` : ''
        } ${table.border ? 'border border-[#bbbbbb]' : ''} overflow-hidden`}
      >
        {children(ctx, cell.c, inner)}
      </div>
    )
  }
  return (
    <div className={`flex ${bgOf(row.bg, look)} ${row.h ? `min-h-[${px(row.h, look)}px]` : ''}`}>{cells}</div>
  )
}

function renderBox(ctx: Ctx, box: Box, width: number, first: boolean) {
  const look = ctx.look
  let w = width
  const cls: string[] = ['flex flex-col']
  if (box.w) {
    w = Math.min(width, px(box.w, look))
    cls.push(`w-[${w}px]`)
  }
  const bg = bgOf(box.bg, look)
  if (bg) cls.push(bg)
  if (box.mt && !first) cls.push(`mt-[${Math.min(px(box.mt, look), 40)}px]`)
  if (box.h) cls.push(`min-h-[${px(box.h, look)}px]`)
  let inner = w
  if (box.pl) {
    const pl = Math.min(px(box.pl, look), Math.round(w / 3))
    cls.push(`pl-[${pl}px]`)
    inner -= pl
  }
  if (box.bar) {
    cls.push(look.ink ? 'border-l-4 border-[#000000]' : 'border-l-4 border-[#cccccc]')
    inner -= 4
  }
  if (box.bg && !box.mark) {
    // Text on a color of its own gets a little room.
    cls.push('px-[4px]')
    inner -= 8
  }
  if (box.mark) {
    const mw = markWidth(look)
    const flow = box.c.find((c) => c.k === 't') as Flow | undefined
    const st = flow && firstStyle(flow.runs)
    const f = st ? face(st, look) : { cls: `text-[${Math.round(16 * look.k)}px]` }
    return (
      <div className={cls.join(' ')}>
        <div className="flex">
          <div className={`shrink-0 w-[${mw}px] pr-[6px] text-right ${f.cls}`}>{box.mark}</div>
          <div className="flex flex-col flex-1 min-w-0">{children(ctx, box.c, inner - mw)}</div>
        </div>
      </div>
    )
  }
  return <div className={cls.join(' ')}>{children(ctx, box.c, inner)}</div>
}

function children(ctx: Ctx, nodes: Node[], width: number) {
  const out: any[] = []
  for (let i = 0; i < nodes.length; i++) out.push(renderNode(ctx, nodes[i], width, i === 0))
  return out
}

function renderNode(ctx: Ctx, node: Node, width: number, first: boolean): any {
  switch (node.k) {
    case 't':
      return renderFlow(ctx, node, width)
    case 'b':
      return renderBox(ctx, node, width, first)
    case 'tab':
      return renderTable(ctx, node, width)
    case 'hr':
      return <div className={`h-[1px] my-[6px] ${ctx.look.ink ? 'bg-[#000000]' : 'bg-[#bbbbbb]'}`} />
  }
  return null
}

// The page at `width` UI pixels.
export function renderPage(page: Page, width: number, look: Look, act: Act) {
  const key = `${look.k}|${look.minPx}|${look.ink}`
  if (facesFor !== key) {
    faces = new Map()
    facesFor = key
  }
  const ctx: Ctx = { look, act, links: new Map() }
  const pad = Math.round(6 * look.k)
  return (
    <div className={`flex flex-col p-[${pad}px] ${look.ink ? 'bg-[#ffffff]' : page.bg ? `bg-[${page.bg}]` : 'bg-[#ffffff]'}`}>
      {children(ctx, page.root.c, width - pad * 2)}
    </div>
  )
}

// The page as the JSX it was drawn from, for the source view: tags and the
// classes that matter, text cut short.
export function jsxSource(page: Page, look: Look, limit = 400): string[] {
  const out: string[] = []
  const q = (s: string) => s.replace(/[{}<>]/g, (c) => `{'${c}'}`)
  const walk = (n: Node, d: number) => {
    if (out.length > limit) return
    const pad = '  '.repeat(Math.min(d, 12))
    if (n.k === 't') {
      const text = (n.runs as any[])
        .map((r) =>
          r.x !== undefined
            ? r.a
              ? `<a onClick={go("${r.a.length > 48 ? r.a.slice(0, 45) + '...' : r.a}")}>${q(r.x)}</a>`
              : q(r.x)
            : r.br
              ? '<br />'
              : r.img
                ? `<img src="${r.img.slice(0, 40)}" />`
                : r.field !== undefined
                  ? '<input />'
                  : r.btn !== undefined
                    ? `<button>${q(r.btn)}</button>`
                    : ''
        )
        .join('')
      const t = text.length > 160 ? text.slice(0, 157) + '...' : text
      out.push(`${pad}<p${n.align ? ` className="text-${n.align}"` : ''}>${t}</p>`)
      return
    }
    if (n.k === 'hr') {
      out.push(`${pad}<hr />`)
      return
    }
    if (n.k === 'tab') {
      out.push(`${pad}<table${n.bg ? ` className="bg-[${n.bg}]"` : ''}>`)
      for (const row of n.rows) {
        out.push(`${pad}  <tr${row.bg ? ` className="bg-[${row.bg}]"` : ''}>`)
        for (const cell of row.cells) {
          out.push(`${pad}    <td${cell.span ? ` colSpan={${cell.span}}` : ''}>`)
          for (const c of cell.c) walk(c, d + 3)
          out.push(`${pad}    </td>`)
        }
        out.push(`${pad}  </tr>`)
      }
      out.push(`${pad}</table>`)
      return
    }
    const cls = [n.bg ? `bg-[${n.bg}]` : '', n.pl ? `pl-[${n.pl}px]` : '', n.mt ? `mt-[${Math.round(n.mt)}px]` : '']
      .filter(Boolean)
      .join(' ')
    out.push(`${pad}<${n.mark ? 'li' : 'div'}${cls ? ` className="${cls}"` : ''}>`)
    for (const c of n.c) walk(c, d + 1)
    out.push(`${pad}</${n.mark ? 'li' : 'div'}>`)
  }
  walk(page.root, 0)
  if (out.length > limit) out.length = limit
  return out
}

