import { get, onEvent, normalize } from './app'
import { convert, resolve } from './html'

// Hacker News's front page as it is built: a table of tables, the story rows
// in threes, a style sheet for the colors, and a GET form for the search.
const HN = `<html lang="en" op="news"><head><link rel="stylesheet" type="text/css" href="news.css?x1">
<title>Hacker News</title><script>var junk = "<b>not text</b>"</script><style>.gone { display: none }</style></head>
<body><center><table id="hnmain" border="0" cellpadding="0" cellspacing="0" width="85%" bgcolor="#f6f6ef">
<tr><td bgcolor="#ff6600"><table border="0" cellpadding="0" cellspacing="0" width="100%" style="padding:2px"><tr>
<td style="width:18px;padding-right:4px"><a href="https://news.ycombinator.com"><img src="y18.svg" width="18" height="18"></a></td>
<td style="line-height:12pt; height:10px;"><span class="pagetop"><b class="hnname"><a href="news">Hacker News</a></b>
<a href="newest">new</a> | <a href="front">past</a></span></td>
<td style="text-align:right;padding-right:4px;"><span class="pagetop"><a href="login?goto=news">login</a></span></td>
</tr></table></td></tr><tr style='height:10px'/><tr id="bigbox"><td><table border="0" cellpadding="0" cellspacing="0">
<tr class="athing submission" id="1"><td align="right" valign="top" class="title"><span class="rank">1.</span></td>
<td valign="top" class="votelinks"><center><a id='up_1' href='vote?id=1&amp;how=up'><div class='votearrow' title='upvote'></div></a></center></td>
<td class="title"><span class="titleline"><a href="https://example.com/story">A story about frames</a><span class="sitebit comhead"> (<a href="from?site=example.com"><span class="sitestr">example.com</span></a>)</span></span></td></tr>
<tr><td colspan="2"></td><td class="subtext"><span class="subline"><span class="score" id="score_1">42 points</span> by <a href="user?id=marius">marius</a> <span class="age"><a href="item?id=1">2 hours ago</a></span> | <a href="item?id=1">12&nbsp;comments</a></span></td></tr>
<tr class="spacer" style="height:5px"></tr>
<tr><td colspan="2"></td><td class='title'><a href='?p=2' class='morelink' rel='next'>More</a></td></tr>
</table></td></tr><tr><td><span class="gone">hidden words</span>
<center><form method="get" action="//hn.algolia.com/">Search: <input type="text" name="q" size="17"></form></center>
</td></tr></table></center></body></html>`

const CSS = `body { font-size:10pt; color:#828282; }
a:link { color:#000000; text-decoration:none; }
.subtext { font-size: 7pt; color:#828282; }
.subtext a:link, .subtext a:visited { color:#828282; }
@media only screen and (max-width: 750px) { .title { font-size: 20pt } }`

const ITEM = `<html><body><table><tr><td><span class="commtext">A comment with <a href="https://example.org/x">a link</a> and <i>words</i>.<p>Second paragraph<pre><code>  indented code</code></pre></span></td></tr></table></body></html>`

// Every string in the tree, in order.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false || node === true) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  return node.props ? find(node.props.children, test) : null
}

// The element that says `text` and takes a tap.
const tappable = (tree: any, text: string) =>
  find(tree, (n) => !!n.props && typeof n.props.onClick === 'function' && texts(n).join('') === text)

let fetched: string[] = []
function serve(pages: Record<string, string>) {
  fetched = []
  return mock.frameos('useFetch' as any, (url: string) => {
    fetched.push(url)
    const body = pages[url]
    if (body === undefined) return { data: undefined, error: 'getaddrinfo ENOTFOUND', loading: false, ok: false, status: 0 }
    return { data: body, loading: false, ok: true, status: 200 }
  })
}

const PAGES = {
  'https://news.ycombinator.com/': HN,
  'https://news.ycombinator.com/news.css?x1': CSS,
  'https://example.com/story': ITEM,
  'https://news.ycombinator.com/item?id=1': ITEM,
}

const show = (app: any) => get(app, makeContext())
// A fresh browser: an app whose memory starts empty.
const browser = () => makeApp()

describe('the browser', () => {
  it('opens Hacker News and draws its stories without the junk', () => {
    serve(PAGES)
    const tree = show(browser())
    const words = texts(tree).join(' ')
    expect(words).toContain('Hacker News')
    expect(words).toContain('frames')
    expect(words).toContain('42')
    expect(words).toContain('Search:')
    expect(words).not.toContain('not text')
    expect(words).not.toContain('hidden words')
    expect(fetched).toContain('https://news.ycombinator.com/news.css?x1')
  })

  it('opens a link when a word of it is tapped', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), 'frames').props.onClick({})
    const words = texts(show(app)).join(' ')
    expect(fetched[fetched.length - 1]).toBe('https://example.com/story')
    expect(words).toContain('Second paragraph')
    expect(words).toContain('indented')
  })

  it('goes back and forward', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), '12 comments').props.onClick({})
    expect(texts(show(app)).join(' ')).toContain('A comment with')
    expect(onEvent(app, makeContext({ event: 'back' }))).toBe(true)
    expect(texts(show(app)).join(' ')).toContain('Hacker News')
    expect(onEvent(app, makeContext({ event: 'back' }))).toBe(false)
    expect(onEvent(app, makeContext({ event: 'forward' }))).toBe(true)
    expect(texts(show(app)).join(' ')).toContain('A comment with')
  })

  it('searches with what is typed into a page form', () => {
    serve(PAGES)
    const app = browser()
    const field = find(show(app), (n) => n.type === 'input' && n.props.placeholder !== 'Search or type an address')
    field.props.onChange({ target: { value: 'nim lang\n' } })
    show(app)
    expect(fetched[fetched.length - 1]).toBe('https://hn.algolia.com/?q=nim+lang')
  })

  it('opens what is typed into the address bar', () => {
    serve(PAGES)
    const app = browser()
    const bar = find(show(app), (n) => n.type === 'input' && n.props.placeholder === 'Search or type an address')
    bar.props.onChange({ target: { value: 'example.com/story' } })
    bar.props.onKeyDown({ key: 'Enter' })
    expect(texts(show(app)).join(' ')).toContain('Second paragraph')
    expect(fetched[fetched.length - 1]).toBe('https://example.com/story')
  })

  it('holds a link for its menu', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), 'marius').props.onLongPress({})
    const tree = show(app)
    expect(texts(tree).join(' ')).toContain('https://news.ycombinator.com/user?id=marius')
    expect(find(tree, (n) => n.type === 'a' && n.props.href === 'https://news.ycombinator.com/user?id=marius')).toBeTruthy()
  })

  it('says when a page does not load', () => {
    serve({})
    const words = texts(show(browser())).join(' ')
    expect(words).toContain('This page did not load')
    expect(words).toContain('ENOTFOUND')
  })

  it('shows the page as JSX', () => {
    serve(PAGES)
    const app = browser()
    find(show(app), (n) => n.props && typeof n.props.onClick === 'function' && find(n, (c) => c.type === 'path' && c.props.d.startsWith('M14.6'))).props.onClick({})
    expect(texts(show(app)).join('\n')).toContain('onClick={go("https://example.com/story")}')
  })
})

describe('reading HTML', () => {
  it('resolves links as a browser does', () => {
    const base = 'https://news.ycombinator.com/item?id=1'
    expect(resolve('user?id=pg', base)).toBe('https://news.ycombinator.com/user?id=pg')
    expect(resolve('?p=2', 'https://news.ycombinator.com/news')).toBe('https://news.ycombinator.com/news?p=2')
    expect(resolve('//hn.algolia.com/', base)).toBe('https://hn.algolia.com/')
    expect(resolve('../a/./b', 'https://x.org/one/two/three')).toBe('https://x.org/one/a/b')
    expect(resolve('javascript:void(0)', base)).toBe('')
    expect(resolve('#top', base)).toBe('')
  })

  it('takes words as a search and names as addresses', () => {
    expect(normalize('news.ycombinator.com')).toBe('https://news.ycombinator.com')
    expect(normalize('frame os')).toBe('https://lite.duckduckgo.com/lite/?q=frame%20os')
    expect(normalize('localhost:8989/x')).toBe('http://localhost:8989/x')
  })

  it('gives Hacker News its colors and sizes from its style sheet', () => {
    const page = convert(HN, 'https://news.ycombinator.com/', { sheets: [CSS] })
    const runs: any[] = []
    const walk = (n: any) => {
      if (n.k === 't') runs.push(...n.runs)
      else if (n.k === 'b') n.c.forEach(walk)
      else if (n.k === 'tab') n.rows.forEach((r: any) => r.cells.forEach(walk))
    }
    walk(page.root)
    const run = (x: string) => runs.find((r) => r.x !== undefined && r.x.indexOf(x) >= 0)
    expect(run('A story').s.color).toBe('#000000')
    expect(run('A story').a).toBe('https://example.com/story')
    expect(run('marius').s.color).toBe('#828282')
    expect(Math.round(run('marius').s.size)).toBe(9)
    expect(Math.round(run('A story').s.size)).toBe(13)
    expect(page.title).toBe('Hacker News')
    expect(page.forms[0].action).toBe('https://hn.algolia.com/')
  })

  it('closes what a page leaves open', () => {
    const page = convert('<ul><li>one<li>two</ul><p>a<p>b<table><tr><td>x<td>y<tr><td>z</table>', 'https://x.org/')
    const kinds = page.root.c.map((n: any) => n.k)
    expect(kinds).toEqual(['b', 'b', 'b', 'tab'])
    const table: any = page.root.c[3]
    expect(table.rows.length).toBe(2)
    expect(table.rows[0].cells.length).toBe(2)
  })
})
